356	Vec2 PhysicsCollisionPair::computeRelativeVelocity() const
357	{
358	    if (_arbiter == nullptr || !_valid)
359	    {
360	        return Vec2::ZERO;
361	    }
362	
363	    cpShape* cpShapeA = nullptr;
364	    cpShape* cpShapeB = nullptr;
365	    cpArbiterGetShapes(_arbiter, &cpShapeA, &cpShapeB);
366	
367	    if (cpShapeA == nullptr || cpShapeB == nullptr)
368	    {
369	        return Vec2::ZERO;
370	    }
371	
372	    cpBody* bodyA = cpShapeGetBody(cpShapeA);
373	    cpBody* bodyB = cpShapeGetBody(cpShapeB);
374	
375	    if (bodyA == nullptr || bodyB == nullptr)
376	    {
377	        return Vec2::ZERO;
378	    }
379	
380	    cpVect centre = PhysicsHelper::point2cpv(computeContactCenter());
381	    Vec2 velocityA = PhysicsHelper::cpv2point(cpBodyGetVelocityAtWorldPoint(bodyA, centre));
382	    Vec2 velocityB = PhysicsHelper::cpv2point(cpBodyGetVelocityAtWorldPoint(bodyB, centre));
383	
384	    return velocityB - velocityA;
385	}
386	
387	Vec2 PhysicsCollisionPair::computeContactCenter() const
388	{
389	    int count = getContactCount();
390	    if (count <= 0)
391	    {
392	        return Vec2::ZERO;
393	    }
394	
395	    Vec2 sum = Vec2::ZERO;
396	    for (int i = 0; i < count; ++i)
397	    {
398	        Vec2 pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(_arbiter, i));
399	        Vec2 pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(_arbiter, i));
400	        sum += (pointA + pointB) * 0.5f;
401	    }
402	
403	    return sum / static_cast<float>(count);
404	}
